std::wstring utf8w(const std::string&s){if(s.empty())return{};int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);std::wstring w(n,0);MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),w.data(),n);return w;}
std::string wutf8(const std::wstring&w){if(w.empty())return{};int n=WideCharToMultiByte(CP_UTF8,0,w.data(),(int)w.size(),nullptr,0,nullptr,nullptr);std::string s(n,0);WideCharToMultiByte(CP_UTF8,0,w.data(),(int)w.size(),s.data(),n,nullptr,nullptr);return s;}
std::wstring machine_guid(){wchar_t b[256]{};DWORD z=sizeof(b);if(RegGetValueW(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Microsoft\\Cryptography",L"MachineGuid",RRF_RT_REG_SZ,nullptr,b,&z)==ERROR_SUCCESS)return b;z=sizeof(b);GetComputerNameW(b,&z);return b;}
std::array<BYTE,32> sha256(const void*p,size_t n){std::array<BYTE,32> out{};BCRYPT_ALG_HANDLE a{};BCRYPT_HASH_HANDLE h{};DWORD objn=0,q=0;std::vector<BYTE>obj;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)return out;BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,(PUCHAR)&objn,sizeof(objn),&q,0);obj.resize(objn);if(BCryptCreateHash(a,&h,obj.data(),objn,nullptr,0,0)>=0){BCryptHashData(h,(PUCHAR)p,(ULONG)n,0);BCryptFinishHash(h,out.data(),(ULONG)out.size(),0);BCryptDestroyHash(h);}BCryptCloseAlgorithmProvider(a,0);return out;}
std::wstring license_dir(){PWSTR p{};std::wstring d;if(SUCCEEDED(SHGetKnownFolderPath(FOLDERID_ProgramData,0,nullptr,&p))){d=p;CoTaskMemFree(p);}else d=L"C:\\ProgramData";d+=L"\\WolfDAB";CreateDirectoryW(d.c_str(),nullptr);return d;}
std::wstring license_path(){wchar_t test[32768]{};DWORD n=GetEnvironmentVariableW(L"WOLFDAB_LICENSE_PATH",test,32768);if(n&&n<32768)return test;return license_dir()+L"\\license.dat";}
std::wstring read_file(){HANDLE h=CreateFileW(license_path().c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,0,nullptr);if(h==INVALID_HANDLE_VALUE)return{};DWORD n=GetFileSize(h,nullptr),got=0;std::string s(n,0);ReadFile(h,s.data(),n,&got,nullptr);CloseHandle(h);s.resize(got);return utf8w(s);}
bool write_file(const std::wstring&code,const std::wstring&location){std::string s=wutf8(code+L"\n"+location+L"\n");HANDLE h=CreateFileW(license_path().c_str(),GENERIC_WRITE,0,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE)return false;DWORD put=0;bool ok=WriteFile(h,s.data(),(DWORD)s.size(),&put,nullptr)&&put==s.size();CloseHandle(h);return ok;}
std::vector<BYTE>b64url(std::wstring s){std::replace(s.begin(),s.end(),L'-',L'+');std::replace(s.begin(),s.end(),L'_',L'/');while(s.size()%4)s+=L'=';DWORD n=0;if(!CryptStringToBinaryW(s.c_str(),0,CRYPT_STRING_BASE64,nullptr,&n,nullptr,nullptr))return{};std::vector<BYTE>b(n);if(!CryptStringToBinaryW(s.c_str(),0,CRYPT_STRING_BASE64,b.data(),&n,nullptr,nullptr))return{};b.resize(n);return b;}
bool der_to_raw(const std::vector<BYTE>&d,std::array<BYTE,64>&raw){size_t p=0;if(d.size()<8||d[p++]!=0x30)return false;size_t seq=d[p++];if(seq&0x80){size_t c=seq&0x7f;seq=0;if(c>2||p+c>d.size())return false;while(c--)seq=(seq<<8)|d[p++];}for(int k=0;k<2;k++){if(p+2>d.size()||d[p++]!=0x02)return false;size_t n=d[p++];if(n&0x80){size_t c=n&0x7f;n=0;if(c>2||p+c>d.size())return false;while(c--)n=(n<<8)|d[p++];}if(p+n>d.size())return false;while(n>32&&d[p]==0){p++;n--;}if(n>32)return false;memcpy(raw.data()+k*32+(32-n),d.data()+p,n);p+=n;}return true;}
bool validate(const std::wstring&code){size_t a=code.find(L'.'),b=code.find(L'.',a==std::wstring::npos?a:a+1);if(a==std::wstring::npos||b==std::wstring::npos||code.substr(0,a)!=L"WD1")return false;auto payload=b64url(code.substr(a+1,b-a-1)),der=b64url(code.substr(b+1));std::string expected="WolfDAB|"+wutf8(installation_code());if(payload.size()!=expected.size()||memcmp(payload.data(),expected.data(),expected.size()))return false;std::array<BYTE,64>sig{};if(!der_to_raw(der,sig))return false;struct Blob{BCRYPT_ECCKEY_BLOB h;BYTE xy[64];}blob{{BCRYPT_ECDSA_PUBLIC_P256_MAGIC,32},{}};memcpy(blob.xy,public_x,32);memcpy(blob.xy+32,public_y,32);BCRYPT_ALG_HANDLE alg{};BCRYPT_KEY_HANDLE key{};bool ok=false;auto hash=sha256(payload.data(),payload.size());if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_ECDSA_P256_ALGORITHM,nullptr,0)>=0){if(BCryptImportKeyPair(alg,nullptr,BCRYPT_ECCPUBLIC_BLOB,&key,(PUCHAR)&blob,sizeof(blob),0)>=0){ok=BCryptVerifySignature(key,nullptr,hash.data(),(ULONG)hash.size(),sig.data(),(ULONG)sig.size(),0)>=0;BCryptDestroyKey(key);}BCryptCloseAlgorithmProvider(alg,0);}return ok;}
std::wstring json_escape(const std::wstring&s){std::wstring o;for(wchar_t c:s){if(c==L'\\'||c==L'"'){o+=L'\\';o+=c;}else if(c==L'\r')o+=L"\\r";else if(c==L'\n')o+=L"\\n";else o+=c;}return o;}
bool post(const wchar_t*path,const std::wstring&body,std::string&response,DWORD&status){HINTERNET ses=WinHttpOpen(L"WolfDAB/1.0",WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0);if(!ses)return false;WinHttpSetTimeouts(ses,12000,12000,12000,12000);HINTERNET con=WinHttpConnect(ses,endpoint_host,INTERNET_DEFAULT_HTTPS_PORT,0);HINTERNET req=con?WinHttpOpenRequest(con,L"POST",path,nullptr,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,WINHTTP_FLAG_SECURE):nullptr;std::string u=wutf8(body);bool ok=req&&WinHttpSendRequest(req,L"Content-Type: application/json; charset=utf-8\r\n",-1L,(LPVOID)u.data(),(DWORD)u.size(),(DWORD)u.size(),0)&&WinHttpReceiveResponse(req,nullptr);DWORD z=sizeof(status);if(ok)WinHttpQueryHeaders(req,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,nullptr,&status,&z,nullptr);if(ok){for(;;){DWORD avail=0;if(!WinHttpQueryDataAvailable(req,&avail)||!avail)break;size_t old=response.size();response.resize(old+avail);DWORD got=0;if(!WinHttpReadData(req,response.data()+old,avail,&got)){response.resize(old);break;}response.resize(old+got);}}if(req)WinHttpCloseHandle(req);if(con)WinHttpCloseHandle(con);WinHttpCloseHandle(ses);return ok;}
bool activate_online(const std::wstring&code,const std::wstring&location,std::wstring&error){std::wstring body=L"{\"code\":\""+json_escape(code)+L"\",\"installationCode\":\""+json_escape(installation_code())+L"\",\"location\":\""+json_escape(location)+L"\"}";std::string response;DWORD status=0;if(!post(endpoint_path,body,response,status)){error=L"network";return false;}if(status!=200||response.find("\"valid\":true")==std::string::npos){error=response.find("another computer")!=std::string::npos?L"used":L"invalid";return false;}return true;}
bool request_code(const std::wstring&name,const std::wstring&email,const std::wstring&location,int language){std::wstring body=L"{\"installationCode\":\""+json_escape(installation_code())+L"\",\"name\":\""+json_escape(name)+L"\",\"email\":\""+json_escape(email)+L"\",\"location\":\""+json_escape(location)+L"\",\"language\":"+std::to_wstring(language)+L"}";std::string response;DWORD status=0;bool ok=post(L"/WolfDAB_license/request.php",body,response,status);return ok&&status==200&&response.find("\"sent\":true")!=std::string::npos;}

