std::wstring installation_code(){std::string seed="WolfDAB|"+wutf8(machine_guid());auto h=sha256(seed.data(),seed.size());std::wstring r;const wchar_t*hex=L"0123456789ABCDEF";for(int i=0;i<12;i++){if(i&&i%2==0)r+=L'-';r+=hex[h[i]>>4];r+=hex[h[i]&15];}return r;}
bool is_registered(){std::wstring all=read_file();size_t n=all.find_first_of(L"\r\n");return validate(all.substr(0,n));}
bool show_registration(HWND owner,int language){RegState s{};s.lang=language;WNDCLASSW c{};c.hInstance=GetModuleHandleW(nullptr);c.lpszClassName=L"WolfDABRegistration";c.lpfnWndProc=reg_proc;c.hCursor=LoadCursor(nullptr,IDC_ARROW);c.hbrBackground=(HBRUSH)(COLOR_WINDOW+1);RegisterClassW(&c);HWND h=CreateWindowExW(WS_EX_DLGMODALFRAME,c.lpszClassName,L"WolfDAB — Registration / Registrazione",WS_CAPTION|WS_SYSMENU,0,0,680,585,owner,nullptr,c.hInstance,&s);RECT rc{},ro{};GetWindowRect(h,&rc);if(owner)GetWindowRect(owner,&ro);else SystemParametersInfoW(SPI_GETWORKAREA,0,&ro,0);SetWindowPos(h,HWND_TOP,(ro.left+ro.right-(rc.right-rc.left))/2,(ro.top+ro.bottom-(rc.bottom-rc.top))/2,0,0,SWP_NOSIZE);if(owner)EnableWindow(owner,FALSE);ShowWindow(h,SW_SHOW);MSG m;while(IsWindow(h)&&GetMessageW(&m,nullptr,0,0)){if(!IsDialogMessageW(h,&m)){TranslateMessage(&m);DispatchMessageW(&m);}}if(owner){EnableWindow(owner,TRUE);SetForegroundWindow(owner);}return s.success;}
